<script setup lang="ts">
import { computed } from 'vue'
const props = defineProps<{ items: Record<string, unknown>[] }>()
const colors: Record<string,string> = { historical_blocks:'#28784d',glm_hurdle:'#5277b5',xgboost_hurdle:'#bd8038' }
const names: Record<string,string> = {historical_blocks:'历史收益分块重采样',glm_hurdle:'Logistic＋Gamma',xgboost_hurdle:'两阶段 XGBoost'}
const points = computed(() => props.items.filter(item => typeof item.predicted_probability === 'number' && typeof item.observed_frequency === 'number' && item.predicted_probability >= 0 && item.predicted_probability <= 1 && item.observed_frequency >= 0 && item.observed_frequency <= 1))
</script>
<template><figure v-if="points.length" class="calibration-figure"><svg viewBox="0 0 440 280" role="img" aria-label="概率可靠性图：横轴为平均预测概率，纵轴为实际触发频率，虚线为理想一致线"><path d="M50 20V230H410" fill="none" stroke="#9caea0"/><path d="M50 230L410 20" fill="none" stroke="#9caea0" stroke-dasharray="5 5"/><g v-for="tick in [0,.5,1]" :key="tick"><text :x="50+360*tick" y="248" text-anchor="middle">{{ tick*100 }}%</text><text x="42" :y="234-210*tick" text-anchor="end">{{ tick*100 }}%</text></g><text x="230" y="275" text-anchor="middle">平均预测概率</text><text x="55" y="13">实际触发频率</text><circle v-for="(point,index) in points" :key="index" :cx="50+360*Number(point.predicted_probability)" :cy="230-210*Number(point.observed_frequency)" r="5" :fill="colors[String(point.method_id)] || '#777'"><title>{{ names[String(point.method_id)] || point.method_id }}：预测 {{ (100*Number(point.predicted_probability)).toFixed(1) }}%，实际 {{ (100*Number(point.observed_frequency)).toFixed(1) }}%，{{ point.sample_count }} 条样本</title></circle></svg><figcaption><span v-for="method in [...new Set(points.map(p=>String(p.method_id)))]" :key="method" :style="{color:colors[method]}">● {{ names[method] || method }}　</span><p>每点为一个概率分箱；虚线表示预测与实际一致。分箱样本量见下表；未绘制未经估计的置信区间。</p></figcaption></figure></template>
<style scoped>.calibration-figure{margin:16px 0;max-width:600px}.calibration-figure svg{width:100%;max-height:320px}.calibration-figure text{font-size:11px;fill:#748078}.calibration-figure figcaption{font-size:11px;line-height:1.8}</style>
